SELECT *, NTILE(4) OVER (PARTITION BY city ORDER BY rating DESC, id) AS rating_bucket, SUM(rating) OVER (PARTITION BY country) AS country_sum_rating, AVG(rating) OVER (ORDER BY rating, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS rating_avg_6, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating DESC, id) AS event_seq, CUME_DIST() OVER (PARTITION BY city ORDER BY rating DESC NULLS FIRST) AS rating_cume_dist FROM suppliers
